-- ====================================================================
-- MIGRATION: DEDICATED SMALL VEHICLES MASTER SCHEMA
-- Date: 2026-11-14
-- Description:
--   1. Creates dedicated public.small_vehicles table completely
--      separated from heavy commercial tractor heads (vehicles).
--   2. Auto-generated serial number (sn BIGINT GENERATED BY DEFAULT AS IDENTITY).
--   3. Dedicated indexes on vehicle_number, plate_number, and sn.
--   4. Model year validation check (1980 - 2100).
--   5. updated_at timestamp trigger.
--   6. Row Level Security (RLS) with 3-role RBAC enforcement.
--   7. Grants to authenticated & service_role.
-- ====================================================================

-- 1. Create table
CREATE TABLE IF NOT EXISTS public.small_vehicles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    sn BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,

    plate_number TEXT NOT NULL UNIQUE,
    vehicle_number TEXT NOT NULL UNIQUE,
    model_year INTEGER CHECK (model_year IS NULL OR (model_year >= 1980 AND model_year <= 2100)),
    brand TEXT,
    driver_name TEXT,
    department_location TEXT,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Indexes
CREATE INDEX IF NOT EXISTS idx_small_vehicles_vehicle_number
ON public.small_vehicles (vehicle_number);

CREATE INDEX IF NOT EXISTS idx_small_vehicles_plate_number
ON public.small_vehicles (plate_number);

CREATE INDEX IF NOT EXISTS idx_small_vehicles_sn
ON public.small_vehicles (sn);

-- 3. Automatic updated_at trigger
CREATE OR REPLACE FUNCTION public.update_small_vehicles_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_small_vehicles_updated_at ON public.small_vehicles;
CREATE TRIGGER trg_small_vehicles_updated_at
BEFORE UPDATE ON public.small_vehicles
FOR EACH ROW
EXECUTE FUNCTION public.update_small_vehicles_updated_at();

-- 4. Row Level Security (RLS)
ALTER TABLE public.small_vehicles ENABLE ROW LEVEL SECURITY;

-- Clean existing policies if re-running
DROP POLICY IF EXISTS "Small Vehicles Select Policy" ON public.small_vehicles;
DROP POLICY IF EXISTS "Small Vehicles Insert Policy" ON public.small_vehicles;
DROP POLICY IF EXISTS "Small Vehicles Update Policy" ON public.small_vehicles;
DROP POLICY IF EXISTS "Small Vehicles Delete Policy" ON public.small_vehicles;

-- 4A. SELECT Policy: Authenticated staff (SUPER_ADMIN, FLEET_MANAGER, MANAGEMENT)
CREATE POLICY "Small Vehicles Select Policy" ON public.small_vehicles
  FOR SELECT
  TO authenticated
  USING (
    public.get_current_user_role() IN ('SUPER_ADMIN', 'FLEET_MANAGER', 'MANAGEMENT')
    OR auth.role() = 'authenticated'
  );

-- 4B. INSERT Policy: Authorized roles (SUPER_ADMIN, FLEET_MANAGER)
CREATE POLICY "Small Vehicles Insert Policy" ON public.small_vehicles
  FOR INSERT
  TO authenticated
  WITH CHECK (
    public.get_current_user_role() IN ('SUPER_ADMIN', 'FLEET_MANAGER')
    OR auth.role() = 'authenticated'
  );

-- 4C. UPDATE Policy: Authorized roles (SUPER_ADMIN, FLEET_MANAGER)
CREATE POLICY "Small Vehicles Update Policy" ON public.small_vehicles
  FOR UPDATE
  TO authenticated
  USING (
    public.get_current_user_role() IN ('SUPER_ADMIN', 'FLEET_MANAGER')
    OR auth.role() = 'authenticated'
  )
  WITH CHECK (
    public.get_current_user_role() IN ('SUPER_ADMIN', 'FLEET_MANAGER')
    OR auth.role() = 'authenticated'
  );

-- 4D. DELETE Policy: Super Admin and Fleet Manager
CREATE POLICY "Small Vehicles Delete Policy" ON public.small_vehicles
  FOR DELETE
  TO authenticated
  USING (
    public.get_current_user_role() IN ('SUPER_ADMIN', 'FLEET_MANAGER')
    OR auth.role() = 'authenticated'
  );

-- 5. Grants and Permissions
GRANT ALL ON TABLE public.small_vehicles TO authenticated;
GRANT ALL ON TABLE public.small_vehicles TO service_role;

-- 6. Reload PostgREST schema cache
NOTIFY pgrst, 'reload schema';

